const raw = $input.first().json;
const body = raw.body && typeof raw.body === 'object' ? raw.body : raw;
const clean = v => (v === undefined || v === null) ? '' : String(v).trim();
const action = clean(body.action).toLowerCase();
const out = { route: 'invalid', action, errors: [] };

if (action === 'search_site') {
  out.query = clean(body.query || body.question || body.q).slice(0, 300);
  out.max_results = Math.min(Math.max(parseInt(body.max_results, 10) || 4, 1), 6);
  out.route = 'search_site';
} else if (action === 'capture_lead') {
  const email = clean(body.email).toLowerCase().replace(/\s+/g, '');
  const phone = clean(body.phone).replace(/[^\d+]/g, '');
  const emailOk = /^[^@\s]+@[^@\s]+\.[a-z]{2,}$/i.test(email);
  if (!emailOk && phone.replace(/\D/g, '').length < 10) out.errors.push('a valid email (or phone number) is required');
  if (email && !emailOk) out.errors.push('email looks invalid; confirm it with the visitor');
  const need = clean(body.need || body.topic || body.project);
  if (!need) out.errors.push('need is required: one sentence describing what the visitor wants help with');
  const now = DateTime.now().setZone('America/New_York');
  out.lead = {
    lead_id: 'WL-' + now.toFormat('yyMMdd') + '-' + Math.random().toString(36).slice(2, 7).toUpperCase(),
    name: clean(body.name || body.visitor_name),
    email: emailOk ? email : '',
    phone,
    company: clean(body.company || body.business),
    need,
    notes: clean(body.notes || body.summary).slice(0, 2000),
    interest_level: ['hot', 'warm', 'cold'].includes(clean(body.interest_level).toLowerCase()) ? clean(body.interest_level).toLowerCase() : 'warm',
    preferred_follow_up: clean(body.preferred_follow_up || body.follow_up) || (emailOk ? 'email' : 'phone'),
    source: 'website_chat',
    status: 'new',
  };
  out.received = now.toFormat("ccc LLL d, h:mm a 'ET'");
  out.route = out.errors.length ? 'invalid' : 'capture_lead';
} else {
  out.errors.push('unknown action; use search_site or capture_lead');
}
out.response = out.errors.length
  ? { status: 'invalid_request', errors: out.errors, message: 'Missing or unclear details: ' + out.errors.join('; ') + '.' }
  : { status: 'ok' };
return [{ json: out }];

